"""Writes sample CSV files for a LIVE semester, generated by the simulator, so the CSV import can be tried end to end.

    .venv\\Scripts\\python tools\\make_sample_csv.py                      (baseline: meals 0-41)
    .venv\\Scripts\\python tools\\make_sample_csv.py --meals 9 --seed 7

Writes samples/menus.csv and samples/observations.csv. Every meal is served in the neutral (P0) layout, which is
what the import does for baseline meals. Unless --no-dishes is given, it also adds the simulator's dishes to the
backend's dish catalogue through the API (dishes that already exist are skipped), because menu rows refer to dishes
by name. The backend must be running for that step.
"""
import argparse
import csv
import json
import pathlib
import sys
import urllib.error
import urllib.request

ROOT = pathlib.Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "python"))

from simulator.catalogue import DISHES, dish_id  # noqa: E402
from simulator.mess import MessSimulator  # noqa: E402


def add_dishes(api: str) -> None:
    added = skipped = 0
    for name, d in DISHES.items():
        body = json.dumps({"name": name, "category": d.category, "carbonKgPerServing": d.carbon_kg,
                           "portionMassG": d.portion_g, "eligibleByDefault": d.role == "ELIGIBLE"}).encode()
        req = urllib.request.Request(api.rstrip("/") + "/api/dishes", data=body, method="POST",
                                     headers={"Content-Type": "application/json"})
        try:
            urllib.request.urlopen(req, timeout=10).close()
            added += 1
        except urllib.error.HTTPError as e:
            if e.code != 409:
                raise SystemExit(f"adding dish {name} failed: HTTP {e.code} {e.read().decode(errors='replace')}")
            skipped += 1
        except urllib.error.URLError as e:
            raise SystemExit(f"cannot reach the backend at {api} ({e.reason}); start it or use --no-dishes")
    print(f"dishes: {added} added, {skipped} already in the catalogue")


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--seed", type=int, default=100)
    ap.add_argument("--scenario", default="SUCCESSFUL_NUDGING")
    ap.add_argument("--meals", type=int, default=42, help="how many meals from the start (default: the baseline)")
    ap.add_argument("--out", default=str(ROOT / "samples"))
    ap.add_argument("--api", default="http://localhost:8080")
    ap.add_argument("--no-dishes", action="store_true")
    args = ap.parse_args()

    config = json.loads((ROOT / "config" / "experiment_config.v1.json").read_text(encoding="utf-8"))
    sim = MessSimulator(args.seed, args.scenario, config)
    names = {dish_id(n): n for n in DISHES}
    out = pathlib.Path(args.out)
    out.mkdir(parents=True, exist_ok=True)

    with open(out / "menus.csv", "w", newline="", encoding="utf-8") as fm, \
            open(out / "observations.csv", "w", newline="", encoding="utf-8") as fo:
        menus, obs_out = csv.writer(fm), csv.writer(fo)
        menus.writerow(["date", "meal_type", "dish", "slot", "expected_attendance", "role"])
        obs_out.writerow(["date", "meal_type", "dish", "portions_taken", "waste_g", "attendance", "total_waste_g"])
        for t in range(min(args.meals, sim.n_meals)):
            spec = sim.meal_spec(t)
            meal = spec["meal"]
            items = sorted(spec["menu_items"], key=lambda i: i["standard_slot"])
            by_id = {i["id"]: i for i in items}
            for i in items:
                menus.writerow([meal["date"], meal["meal_type"], names[i["dish_id"]], i["standard_slot"],
                                meal["expected_attendance"], i["role"]])
            neutral = [i["id"] for i in items if i["role"] == "ELIGIBLE"]
            observation, _truth = sim.step(t, neutral)
            for o in observation["item_outcomes"]:
                waste = "" if o.get("waste_g") is None else o["waste_g"]
                obs_out.writerow([meal["date"], meal["meal_type"], names[by_id[o["menu_item_id"]]["dish_id"]],
                                  o["portions_taken"], waste, observation["actual_attendance"],
                                  observation["aggregate_waste_g"]])
    print(f"wrote {out / 'menus.csv'} and {out / 'observations.csv'} ({min(args.meals, sim.n_meals)} meals)")
    if not args.no_dishes:
        add_dishes(args.api)


if __name__ == "__main__":
    main()